def leading_space_each_offense(processed_source, node, cop_config)
  @leading_continuation_cache ||= {}
  return unless node.source.include?('\\')

  end_of_first_line = node.source_range.begin_pos - node.source_range.column
  lines = leading_space_raw_lines(processed_source, node)
  offenses = []
  lines.each_cons(2).with_index(node.first_line) do |(raw_line_one, raw_line_two), line_num|
    end_of_first_line += raw_line_one.length
    next unless leading_space_continuation?(raw_line_one, line_num, node)

    offense = leading_space_offense_for_pair(raw_line_one, raw_line_two, end_of_first_line, cop_config)
    next unless offense

    offenses << offense
    yield(*offense) if block_given?
  end
  @leading_continuation_cache[:offenses] = offenses
  offenses
end

def leading_space_offense_for_pair(first_line, second_line, end_of_first_line, cop_config)
  @leading_continuation_cache ||= {}
  if leading_space_style_leading?(cop_config)
    matches = leading_space_match_leading_offense(first_line)
    return unless matches

    bounds = leading_space_leading_bounds(end_of_first_line, matches)
    insert_pos = leading_space_leading_insert_pos(end_of_first_line, second_line)
    @leading_continuation_cache[:last_pair] = [bounds, insert_pos, matches[:trailing_spaces]]
    [bounds, insert_pos, matches[:trailing_spaces]]
  else
    matches = leading_space_match_trailing_offense(second_line)
    return unless matches

    bounds = leading_space_trailing_bounds(end_of_first_line, matches)
    insert_pos = leading_space_trailing_insert_pos(end_of_first_line, first_line)
    @leading_continuation_cache[:last_pair] = [bounds, insert_pos, matches[:leading_spaces]]
    [bounds, insert_pos, matches[:leading_spaces]]
  end
end

def leading_space_build_range(buffer, begin_pos, end_pos)
  @leading_continuation_cache ||= {}
  range = Parser::Source::Range.new(buffer, begin_pos, end_pos)
  @leading_continuation_cache[:last_range] = range
  range
end

def alignment_allow_for_alignment?(cop_config)
  @token_spacing_cache ||= {}
  @token_spacing_cache[:allow_for_alignment] = cop_config['AllowForAlignment']
  @token_spacing_cache[:allow_for_alignment]
end

def alignment_assignment_tokens(processed_source)
  @token_spacing_cache ||= {}
  cached = @token_spacing_cache[:assignment_tokens]
  return cached if cached

  tokens = processed_source.tokens.select(&:equal_sign?)
  tokens = alignment_remove_optarg_equals(tokens, processed_source)
  unique_tokens = Set.new(tokens.uniq(&:line))
  @token_spacing_cache[:assignment_tokens] = unique_tokens
  unique_tokens
end

def alignment_assignment_lines(processed_source)
  @token_spacing_cache ||= {}
  cached = @token_spacing_cache[:assignment_lines]
  return cached if cached

  lines = alignment_assignment_tokens(processed_source).map(&:line)
  @token_spacing_cache[:assignment_lines] = lines
  lines
end

def alignment_remove_optarg_equals(asgn_tokens, processed_source)
  @token_spacing_cache ||= {}
  ast = processed_source.ast
  unless ast
    @token_spacing_cache[:optarg_equals] = asgn_tokens
    return asgn_tokens
  end

  optargs = ast.each_node(:optarg)
  optarg_eql = optargs.to_set { |optarg| optarg.loc.operator.begin_pos }
  filtered = asgn_tokens.reject { |token| optarg_eql.include?(token.begin_pos) }
  @token_spacing_cache[:optarg_equals] = filtered
  filtered
end

def alignment_comment_lines(processed_source)
  @token_spacing_cache ||= {}
  cached = @token_spacing_cache[:comment_lines]
  return cached if cached

  lines = processed_source.comments.map(&:loc).select do |range|
    begins_its_line?(range.expression)
  end.map(&:line)
  @token_spacing_cache[:comment_lines] = lines
  lines
end

def alignment_aligned_words?(range, line)
  @token_spacing_cache ||= {}
  left_edge = range.column
  if left_edge.positive? && /\s\S/.match?(line[left_edge - 1, 2])
    @token_spacing_cache[:aligned_words] = true
    return true
  end

  token = range.source
  aligned = token == line[left_edge, token.length]
  @token_spacing_cache[:aligned_words] = aligned
  aligned
end

def alignment_aligned_identical?(range, line)
  @token_spacing_cache ||= {}
  identical = range.source == line[range.column, range.size]
  @token_spacing_cache[:aligned_identical] = identical
  identical
end

def alignment_aligned_with_preceding_assignment_token?(range, token)
  @token_spacing_cache ||= {}
  unless token
    @token_spacing_cache[:preceding_assignment] = false
    return false
  end

  aligned = range.source[-1] == '=' && range.last_column == token.pos.last_column
  @token_spacing_cache[:preceding_assignment] = aligned
  aligned
end

def alignment_aligned_with_append_operator?(range, token)
  @token_spacing_cache ||= {}
  unless token
    @token_spacing_cache[:append_operator] = false
    return false
  end

  append_match = ((range.source == '<<' && token.equal_sign?) ||
    (range.source[-1] == '=' && token.type == :tLSHFT)) &&
    range.last_column == token.pos.last_column
  @token_spacing_cache[:append_operator] = append_match
  append_match
end

def alignment_aligned_assignment?(range, lineno, processed_source)
  @token_spacing_cache ||= {}
  line_range = processed_source.buffer.line_range(lineno)
  unless line_range
    @token_spacing_cache[:aligned_assignment] = false
    return false
  end

  assignment_token = processed_source.tokens_within(line_range).detect do |token|
    token.equal_sign? || token.type == :tLSHFT
  end
  aligned = alignment_aligned_with_preceding_assignment_token?(range, assignment_token) ||
            alignment_aligned_with_append_operator?(range, assignment_token)
  @token_spacing_cache[:aligned_assignment] = aligned
  aligned
end

def alignment_aligned_token?(range, line, lineno, processed_source)
  @token_spacing_cache ||= {}
  aligned = alignment_aligned_words?(range, line) ||
            alignment_aligned_assignment?(range, lineno, processed_source)
  @token_spacing_cache[:aligned_token] = aligned
  aligned
end

def alignment_aligned_operator?(range, line, lineno, processed_source)
  @token_spacing_cache ||= {}
  aligned = alignment_aligned_identical?(range, line) ||
            alignment_aligned_assignment?(range, lineno, processed_source)
  @token_spacing_cache[:aligned_operator] = aligned
  aligned
end

def alignment_aligned_with_line?(line_nos, range, processed_source, kind, indent = nil)
  @token_spacing_cache ||= {}
  comment_lines = alignment_comment_lines(processed_source)
  line_nos.each do |lineno|
    next if comment_lines.include?(lineno + 1)

    line = processed_source.lines[lineno]
    index = line =~ /\S/
    next unless index
    next if indent && indent != index

    matched = if kind == :operator
                alignment_aligned_operator?(range, line, lineno + 1, processed_source)
              else
                alignment_aligned_token?(range, line, lineno + 1, processed_source)
              end
    @token_spacing_cache[:aligned_with_line] = matched
    return matched
  end
  @token_spacing_cache[:aligned_with_line] = false
  false
end

def alignment_aligned_with_any_line?(line_ranges, range, processed_source, kind, indent = nil)
  @token_spacing_cache ||= {}
  found = line_ranges.any? do |line_nos|
    alignment_aligned_with_line?(line_nos, range, processed_source, kind, indent)
  end
  @token_spacing_cache[:aligned_with_any_line] = found
  found
end

def alignment_aligned_with_any_line_range?(line_ranges, range, processed_source, kind)
  @token_spacing_cache ||= {}
  if alignment_aligned_with_any_line?(line_ranges, range, processed_source, kind)
    @token_spacing_cache[:aligned_with_range] = true
    return true
  end

  source_line = processed_source.lines[range.line - 1]
  base_indentation = source_line =~ /\S/
  found = alignment_aligned_with_any_line?(line_ranges, range, processed_source, kind, base_indentation)
  @token_spacing_cache[:aligned_with_range] = found
  found
end

def alignment_aligned_with_adjacent_line?(range, processed_source, kind)
  @token_spacing_cache ||= {}
  pre = (range.line - 2).downto(0)
  post = range.line.upto(processed_source.lines.size - 1)
  found = alignment_aligned_with_any_line_range?([pre, post], range, processed_source, kind)
  @token_spacing_cache[:aligned_with_adjacent] = found
  found
end

def alignment_aligned_with_something?(range, processed_source, _cop_config)
  @token_spacing_cache ||= {}
  found = alignment_aligned_with_adjacent_line?(range, processed_source, :token)
  @token_spacing_cache[:aligned_with_something] = found
  found
end

def alignment_aligned_with_operator?(range, processed_source, _cop_config)
  @token_spacing_cache ||= {}
  found = alignment_aligned_with_adjacent_line?(range, processed_source, :operator)
  @token_spacing_cache[:aligned_with_operator] = found
  found
end

